'use strict';
const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{load}=require('./legacy-functions.cjs');
const root=path.resolve(process.argv[2]),out=path.resolve(process.argv[3]),server=http.createServer((req,res)=>{try{const file=path.resolve(root,'.'+decodeURIComponent(new URL(req.url,'http://localhost').pathname));if(!file.startsWith(root+path.sep))throw Error('Path');const b=fs.readFileSync(file);res.writeHead(200,{'content-length':b.length});res.end(b);}catch{res.writeHead(404);res.end();}});
server.listen(0,'127.0.0.1',async()=>{let external=0;try{const base='http://127.0.0.1:'+server.address().port+'/',fetchImpl=(input,opts={})=>{const u=new URL(input,base);if(u.origin!==new URL(base).origin||opts.method==='POST'){external++;throw Error('External/API forbidden');}return fetch(u,opts);},reader=require(path.join(root,'shared/search-json.js')).create({fetchImpl,baseUrl:base,cryptoImpl:crypto.webcrypto}),bounded=require(path.join(root,'shared/bounded-search.js')).create({reader,fetchImpl,baseUrl:base}),L=load(root,{fetch:fetchImpl,CMSearchJson:reader,CMBoundedSearch:bounded,AbortSignal,URL}),chat={},cv={};
 chat.years=await L.chat.getPlayerYears('Mike Trout','baseball');chat.normalizedSportYears=await L.chat.getPlayerYears('Mike Trout',' Base ball ');chat.trout2018=await L.chat.getPlayerCards('Mike Trout','baseball','2018');
 cv.owenPage1=await L.cv.searchStaticCards_('Owen Power','hockey',1,50);cv.owenPage2=await L.cv.searchStaticCards_('Owen Power','hockey',2,50);cv.owenAutocomplete=await L.cv.makeChecklistPlayerTypeaheadHits_('Owen Power','hockey',5);cv.broadPage1=await L.cv.searchStaticCards_('topps','',1,50);cv.broadPage2=await L.cv.searchStaticCards_('topps','',2,50);cv.broadTypeahead=await L.cv.searchStaticTypeahead_('topps','',10);
 const cases=[];for(const [name,value]of Object.entries({chat,cv})){const actual=JSON.stringify(value),expected=fs.readFileSync(path.join(__dirname,'reference',name+'.json'),'utf8');assert.equal(actual,expected);cases.push({name,bytes:Buffer.byteLength(actual),sha256:crypto.createHash('sha256').update(actual).digest('hex'),byte_difference:0});}
 assert.equal(external,0);const r={state:'STAGED',result:'PASS',cases,fixtures:{trout_years:chat.years,trout_2018:chat.trout2018.row_count,owen:cv.owenPage1.total,owen_page2:cv.owenPage2.results.length,all_sport_topps:cv.broadPage1.total},external_requests:external};fs.writeFileSync(out,JSON.stringify(r,null,2));console.log(JSON.stringify(r));
 }catch(e){console.error(e.message);process.exitCode=1;}finally{server.close();}});
